import { test, expect } from '@playwright/test';

test.describe('File Upload Button Disabled During Upload', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should disable upload button while file is uploading', async ({ page }) => {
    // Setup: intercept the upload API call
    await page.route('**/api/upload', (route) => {
      route.abort('blockedbyclient');
    });

    // Get the file input using getByLabel
    const fileInput = page.getByLabel('Select file');
    await expect(fileInput).toBeVisible();

    // Select a file
    await fileInput.setInputFiles('playwright/fixtures/test-file.pdf');

    // Get the upload button using getByRole
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await expect(uploadButton).toBeVisible();

    // Verify button is enabled before upload
    await expect(uploadButton).not.toBeDisabled();

    // Click the upload button
    await uploadButton.click();

    // Verify button is disabled during upload
    await expect(uploadButton).toBeDisabled();

    // Wait for the upload to complete (mocked response)
    await page.route('**/api/upload', (route) => {
      route.continue();
    });

    // Wait for the upload to finish
    await page.waitForTimeout(1000);

    // Verify button is enabled after upload
    await expect(uploadButton).not.toBeDisabled();

    // Verify success message appears
    const successMessage = page.getByText(/file uploaded successfully/i);
    await expect(successMessage).toBeVisible();
  });

  test('should re-enable upload button after upload fails', async ({ page }) => {
    // Setup: intercept the upload API call and simulate failure
    await page.route('**/api/upload', (route) => {
      route.abort('failed');
    });

    // Get the file input using getByLabel
    const fileInput = page.getByLabel('Select file');
    await expect(fileInput).toBeVisible();

    // Select a file
    await fileInput.setInputFiles('playwright/fixtures/test-file.pdf');

    // Get the upload button using getByRole
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await expect(uploadButton).toBeVisible();

    // Verify button is enabled before upload
    await expect(uploadButton).not.toBeDisabled();

    // Click the upload button
    await uploadButton.click();

    // Verify button is disabled during upload
    await expect(uploadButton).toBeDisabled();

    // Wait for the upload to fail
    await page.waitForTimeout(1500);

    // Verify error message appears
    const errorMessage = page.getByText(/upload failed/i);
    await expect(errorMessage).toBeVisible();

    // Verify button is re-enabled after failure
    await expect(uploadButton).not.toBeDisabled();

    // Verify error icon is visible
    const errorIcon = page.getByRole('img', { name: /error/i });
    await expect(errorIcon).toBeVisible();
  });
});
